from flask import Flask, request, redirect, render_template_string
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///stocks.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)

class Stock(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    quantity = db.Column(db.Integer, nullable=False)

    def __repr__(self):
        return f'<Stock {self.name} {self.quantity}>'

@app.route('/')
def index():
    form_html = '''
    <form action="/buy_order" method="post">
        Stock Name: <input type="text" name="stock_name" required><br>
        Quantity: <input type="number" name="quantity" min="1" required><br>
        <input type="submit" value="Submit">
    </form>
    '''
    return render_template_string(form_html)

@app.route('/buy_order', methods=['POST'])
def buy_order():
    stock_name = request.form['stock_name']
    quantity = int(request.form['quantity'])

    new_stock = Stock(name=stock_name, quantity=quantity)
    db.session.add(new_stock)
    db.session.commit()

    return redirect('/stock_view')

@app.route('/stock_view')
def stock_view():
    stocks = Stock.query.all()
    stocks_html = '<h2>Stocks in Database:</h2><ul>'
    for stock in stocks:
        stocks_html += f'<li>{stock.name} - {stock.quantity}</li>'
    stocks_html += '</ul>'
    return render_template_string(stocks_html)

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(debug=True)

